"""R18: escritura breve con criterios semánticos, sin clave textual única."""
import json
from pathlib import Path
U=[]
def unit(id,after,title,exp,hint,rows):
 activities=[]
 for i,(story,model,ideas,why) in enumerate(rows):
  criteria=[dict(id='idea'+str(j+1),descripcion=idea) for j,idea in enumerate(ideas)]
  activities.append(dict(id=id+'-v'+str(i+1),enunciado='Escribí '+('una frase' if len(ideas)==1 else 'una o dos frases')+' con tus palabras. '+hint,respuesta_correcta=model,paso_resuelto='Una forma posible: '+model+'\n'+why,visual=dict(tipo='lectura',titulo='Texto para releer',texto=story),rubrica_escritura=criteria))
 U.append(dict(id=id,tema='comprension_lectora_literal_inferida',despues_de=after,titulo=title,explicacion=exp,ejemplo='Una forma posible: '+rows[0][1],pasos=[rows[0][3],'Podés usar otras palabras si conservan la misma idea.'],pista=hint,visual=activities[0]['visual'],actividades=activities))
unit('leng_esc_frase','leng_res_revisar','Escribir una idea con tus palabras','Primero preguntamos quién hace algo y qué hace. Con esas dos partes armamos una frase. Podemos usar otras palabras: chicos y alumnos pueden referirse al mismo grupo. En este paso importa conservar la idea; no hace falta copiar ni agregar todos los detalles.','Contá quién hizo qué.',[
('Los alumnos ordenaron los libros de la biblioteca. Los pusieron por temas en los estantes. Trabajaron durante la mañana.','Los chicos organizaron los libros.', ['Los alumnos ordenaron u organizaron los libros.'],'Conservamos quién actuó y qué hizo; la hora es un detalle.'),
('Las vecinas prepararon una merienda para el club. Llevaron pan, fruta y agua. Usaron las mesas del patio.','Las vecinas organizaron la merienda.', ['Las vecinas prepararon u organizaron una merienda.'],'No hace falta enumerar todos los alimentos para contar la acción central.'),
('El equipo reparó las bicicletas del taller. Ajustó los frenos y cambió piezas gastadas. Al terminar guardó las herramientas.','El equipo arregló las bicicletas.', ['El equipo reparó o arregló las bicicletas.'],'Arreglar y reparar conservan aquí la misma acción.'),
('Los vecinos pintaron el salón del club. Cubrieron el piso antes de empezar. Después limpiaron los pinceles.','Los vecinos pintaron el salón.', ['Los vecinos pintaron el salón del club.'],'Preparar y limpiar acompañan la acción principal de pintar.'),
('Las familias donaron ropa al refugio. La llevaron en bolsas y ayudaron a separarla por talles.','Las familias entregaron ropa al refugio.', ['Las familias donaron o entregaron ropa al refugio.'],'Conservamos quién entregó la ropa y a dónde la llevó.'),
('Los chicos limpiaron la plaza del barrio. Juntaron papeles y los pusieron en bolsas. Luego guardaron los guantes.','Los chicos limpiaron la plaza.', ['Los chicos limpiaron la plaza o retiraron la basura de ella.'],'La frase reúne la acción principal sin repetir todos sus pasos.')])
unit('leng_esc_causa','leng_esc_frase','Escribir el problema y su solución','Una frase puede unir un problema con lo que se hizo para resolverlo. Primero identificamos qué dificultaba algo; después, qué cambió. Usamos porque o por eso cuando corresponda. Revisamos que el problema y la solución no queden al revés.','Contá qué problema había y cómo lo resolvieron.',[
('Una rama tapaba el camino. Los vecinos la retiraron y el paso volvió a quedar libre.','Los vecinos quitaron la rama que bloqueaba el camino.', ['Una rama bloqueaba el camino.','Los vecinos retiraron la rama para liberar el paso.'],'La frase incluye tanto el obstáculo como la acción que lo quitó.'),
('La canilla perdía agua. La encargada cambió una pieza y dejó de gotear.','La encargada arregló la canilla que goteaba cambiando una pieza.', ['La canilla perdía agua o goteaba.','La encargada la reparó cambiando una pieza.'],'Unimos la pérdida con la reparación, sin inventar otro problema.'),
('La puerta no cerraba porque una caja la trababa. Tomás apartó la caja y pudo cerrarla.','Tomás movió la caja que impedía cerrar la puerta.', ['Una caja impedía cerrar la puerta.','Tomás apartó o movió la caja y la puerta pudo cerrarse.'],'La caja es la causa; moverla es la solución.'),
('Los carteles se habían borrado y los visitantes no encontraban el sendero. Los guardaparques los repintaron para orientarlos.','Repintaron los carteles borrados para que los visitantes encontraran el camino.', ['Los carteles borrados dificultaban encontrar el camino.','Los guardaparques repintaron los carteles para orientar a los visitantes.'],'El resumen conserva la relación entre el problema y el arreglo; no es obligatorio repetir el sujeto si se entiende.'),
('Los libros se mojaban por una gotera. El personal arregló el techo y el agua dejó de caer sobre los estantes.','Arreglaron el techo para que la gotera no mojara los libros.', ['Una gotera mojaba los libros.','El personal reparó el techo y detuvo la entrada de agua.'],'Se puede expresar la solución mediante su finalidad si queda claro que la reparación ocurrió.'),
('Las hojas del mural se volaban con el viento. La clase las sujetó con broches y quedaron en su lugar.','La clase sujetó con broches las hojas que el viento hacía volar.', ['El viento hacía volar las hojas del mural.','La clase sujetó las hojas con broches.'],'La frase incluye la dificultad y la acción concreta que la resolvió.')])
unit('leng_esc_resumen','leng_esc_causa','Escribir un resumen breve de dos párrafos','Leemos un párrafo por vez y pensamos qué aporta cada uno. Escribimos una o dos frases que unan las dos ideas principales. Al releer, comprobamos que no falte el resultado y que no hayamos inventado información. El ejemplo muestra una posibilidad, no una frase obligatoria.','Reuní lo principal de los dos párrafos y conservá el resultado.',[
('La clase reunió libros para compartir con el jardín. Cada familia aportó algunos que ya no leía.\n\nLos alumnos revisaron los libros y los entregaron al jardín. Allí los usaron en encuentros de lectura.','La clase juntó libros y los entregó al jardín para compartir lecturas.', ['La clase reunió o recibió libros aportados por las familias.','Los libros se entregaron al jardín para leerlos o compartir lecturas.'],'Incluimos la colecta y el destino de los libros; no hace falta enumerar cada revisión.'),
('Los vecinos querían usar un terreno abandonado como huerta. Limpiaron el lugar y prepararon la tierra.\n\nDespués sembraron verduras y se organizaron para regarlas. El terreno quedó convertido en una huerta compartida.','Los vecinos transformaron un terreno abandonado en una huerta que cuidan entre todos.', ['Los vecinos recuperaron o transformaron un terreno abandonado.','Crearon una huerta y se organizaron para cuidarla en conjunto.'],'Transformar reúne varias acciones; el resultado debe seguir siendo una huerta compartida.'),
('Los chicos escribieron cuentos para la biblioteca. Al leerlos juntos descubrieron partes que no se entendían.\n\nRevisaron las frases confusas y agregaron información. Luego compartieron las versiones nuevas con los lectores.','Los chicos revisaron sus cuentos para que se entendieran y compartieron las versiones mejoradas.', ['Los chicos revisaron o aclararon sus cuentos para que se entendieran.','Compartieron las versiones revisadas con lectores o en la biblioteca.'],'Conservamos la mejora y la entrega final, sin afirmar que descartaron los cuentos.'),
('El club recibió juegos donados por las familias. Algunos estaban incompletos y el grupo separó los que podían usarse.\n\nOrganizaron encuentros con esos juegos. Desde entonces los vecinos se reúnen para jugar y compartir la tarde.','El club recibió juegos donados y organizó encuentros para compartirlos.', ['El club recibió juegos donados por las familias.','Organizaron encuentros para usar o compartir los juegos.'],'La recepción y el uso de los juegos son las dos ideas que conectan los párrafos.'),
('La biblioteca quería acercar libros a familias que viven lejos. Preparó bolsas con lecturas para distintas edades.\n\nUna voluntaria lleva las bolsas a los hogares y recoge las anteriores. Así las familias pueden pedir nuevos libros sin viajar hasta la biblioteca.','La biblioteca envía libros a hogares lejanos y los renueva para que las familias puedan leer sin viajar.', ['La biblioteca acerca o lleva libros a familias que viven lejos.','Las bolsas o libros se recogen y renuevan, permitiendo leer desde los hogares.'],'El resumen conserva el servicio a distancia y su continuidad mediante el intercambio.'),
('La escuela preparó una muestra sobre la historia del barrio. Los alumnos entrevistaron a vecinos y reunieron fotografías.\n\nCon ese material escribieron relatos y armaron paneles. Al terminar abrieron la muestra a las familias.','Los alumnos reunieron recuerdos y fotos del barrio y prepararon una muestra para las familias.', ['Los alumnos investigaron o reunieron relatos, recuerdos o fotos sobre el barrio.','Prepararon y compartieron una muestra con las familias.'],'Las entrevistas y las fotos alimentaron la muestra; el resumen conserva también que se compartió.')])
root=Path(__file__).resolve().parents[1];p=root/'src/lib/contenido-bases.js';s=p.read_text(encoding='utf-8');start='// R18: escritura guiada.';end='// FIN R18'
if start in s:s=s[:s.index(start)]+s[s.index(end)+len(end):]
code=start+'\nconst ESCRITURA_R18 = '+json.dumps(U,ensure_ascii=False,indent=2)+""";
for (const unidad of ESCRITURA_R18) {
 const indice=UNIDADES_BASES.findIndex(u=>u.id===unidad.despues_de);
 if(indice<0)throw new Error('Falta el paso anterior de '+unidad.id);
 UNIDADES_BASES.splice(indice+1,0,unidad);
}
"""+end+'\n\n';i=s.index('export const TEMAS_BASES');p.write_text(s[:i]+code+s[i:],encoding='utf-8');print(len(U),'unidades;',len(U)*6,'actividades')
